import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第95章 没接","description":"","frontmatter":{},"headers":[],"relativePath":"第95章_没接.md","filePath":"第95章_没接.md"}'),u={name:"第95章_没接.md"};function _(q,p,r,n,s,c){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第95章-没接" tabindex="-1">第95章 没接 <a class="header-anchor" href="#第95章-没接" aria-label="Permalink to &quot;第95章 没接&quot;">​</a></h1><p>第二年三月，我给她打了一个电话，她没接。</p><p>这件事很小，小到我一开始觉得不该写进来。</p><p>后来我把它写进来了，因为这是这四年里唯一一个我没有等到第二天。</p><p>那天是三月十七号。</p><p>我那天下午知道自己考研没上。</p><p>宁城那个我没考上，第二名也没申到调剂。</p><p>我从教务处出来，三点二十。</p><p>我这边下午四点二十，她那边早上八点二十。</p><p>她那天八点有课。</p><p>我站在教学楼外面，看着那个时间。</p><p>我知道这个点她刚坐下。</p><p>我也知道她那边第一节课手机在包里，她不敢拿出来。</p><p>我还是打了。</p><p>我拨出去以后，听见那个&quot;嘟——&quot;。</p><p>响到第五声，断了。</p><p>她挂掉了。</p><p>不是没接到。</p><p>挂掉是&quot;嘟&quot;变短。</p><p>我站在那里，又打了一次。</p><p>这一次响了六声。</p><p>断了。</p><p>我第二次也没等到她回。</p><p>我那天下午在操场上走了十圈。</p><p>我不知道为什么我数到十我就停了。</p><p>我停下来的原因是我发现我走路的姿势不对：我一只手插在兜里，另一只手一直握着手机。</p><p>我把手从兜里拿出来。</p><p>那天下午五点，我收到一条。</p><p>她说，我今天两节课连上，我手机在包里。</p><p>她说，我第二节课下课看了一眼，我看到两个未接。</p><p>她说，你今天怎么了。</p><p>我说，没什么。</p><p>她说，你打两次。</p><p>我说，我就是想问一个事。</p><p>她说，你问。</p><p>我说，你现在在忙吗。</p><p>她说，我在食堂。</p><p>我说，那你吃饭。</p><p>她说，闻迟。</p><p>她说，你今天讲话不对。</p><p>我说，哪里不对。</p><p>她说，你问我&quot;你现在在忙吗&quot;，你就不是来问事的。</p><p>她说，你要么直接讲，要么你今天不要讲。</p><p>我说，我今天没考上。</p><p>她说，哪个。</p><p>我说，宁城。</p><p>她说，我知道。</p><p>她说，我今天早上六点看到这个学校出分。</p><p>我说，你为什么不问我。</p><p>她隔了很久。</p><p>然后她说了一句我完全没有想到的。</p><p>她说，因为我怕你希望我问。</p><p>她说，你要是希望我问，我今天就要在早上六点给你打。</p><p>她说，我六点打了，你那边是下午一点，你在吃饭。</p><p>她说，你要是在吃饭的时候听我说一句&quot;你考得怎么样&quot;，你今天这一天就毁了。</p><p>她说，我要是不问，你可以自己决定今天什么时候讲。</p><p>她说，所以我不问。</p><p>她说，你现在讲了，很好。</p><p>我说，你六点看到，你到现在才跟我讲你六点看到。</p><p>她说，对。</p><p>她说，我今天一整天在算我该怎么接这句。</p><p>我说，接一句&quot;没考上&quot;要算什么。</p><p>她说，我要算我今天能不能陪你去难受。</p><p>她说，我今天两节课，晚上还要交一个图。</p><p>她说，我要是现在陪你难受，我只能回你一句&quot;啊，那怎么办&quot;。</p><p>她说，你那一句&quot;我今年考不上宁城&quot;，我用一个&quot;那怎么办&quot;接，你会觉得我不当回事。</p><p>她说，我要是认真回，我就要讲一整段。</p><p>她说，我在食堂讲一整段，我明天那个图交不了。</p><p>她说，我今天算了一整天，算的是我今晚十点能不能给你打电话。</p><p>我说，那不用打。</p><p>她说，为什么。</p><p>我说，我今天已经讲完了。</p><p>她说，你讲完了你没有解决。</p><p>我说，我不需要解决。</p><p>她说，你需要。</p><p>她说，你这个人你所有的难受都要有一个人替你收，不然你明年还会为这个难受。</p><p>我说，那我今晚等你十点。</p><p>她说，好。</p><p>那天晚上十点，她打了。</p><p>她那边下午三点。</p><p>她在她们楼后面那条路上走的，一边走一边讲。</p><p>她讲了二十分钟。</p><p>前十二分钟她讲的不是我。</p><p>她讲了她今天怎么过的。</p><p>她说她第一节课她一个字没进去，她在纸上画了三十多个圈。</p><p>她说她中午吃饭的时候在算我是不是已经知道了。</p><p>她说她第二节课她出去上了一个厕所，在厕所里站了六分钟。</p><p>她说她六点去拿了那个图，回来的路上她哭了一次，她在路边站了两分钟，然后她擦干净进去了。</p><p>她说，我今天没有一次能在一个没有人看我的地方哭。</p><p>她说，除了那六分钟。</p><p>她说，我今天在厕所那六分钟里，我在想我该用什么语气跟你讲话。</p><p>她说，我最后决定不用语气。</p><p>她说，我今天不劝你。</p><p>我说，那你讲什么。</p><p>她说，我讲一件我的事，你听不听。</p><p>我说，听。</p><p>她说，我那年退学，我拿到的不是通知书，我拿到的是一个回执。</p><p>她说，回执上写着&quot;该生于本年度未参加普通高等学校招生统一考试&quot;。</p><p>她说，那张纸我到现在还在。</p><p>她说，我一直觉得那是一张罪状。</p><p>她说，我今天告诉你这个，是想说：你手上那个&quot;未录取&quot;，跟我那个&quot;未参加&quot;，是同一种纸。</p><p>她说，这种纸只有你自己留着有用。</p><p>她说，别人看它没有意义。</p><p>她说，你现在不要扔。</p><p>她说，你扔了，你五十岁会想起来你扔过它。</p><p>她说，你留着，你五十岁拿出来看，你会知道自己那年在干什么。</p><p>我说，那你留着了吗。</p><p>她说，我留着。</p><p>她说，我这次搬家，从三个地方搬到四个地方，我一直留着。</p><p>她说，我把它夹在那本你寄给我的画册里。</p><p>她说，就是那一页有压痕的。</p><p>她说，我把那张纸夹在她&quot;想进去站一会儿&quot;的那一页。</p><p>她说，这样我每次翻开，我一次看见两张我人生里最没用的纸。</p><p>她说，我告诉它们两个：你们没用，可是你们没有骗我。</p><p>那天我们讲了二十分钟。</p><p>挂电话以前她说了一句。</p><p>她说，你今天那两个未接，你做得对。</p><p>我说，你不是说你不要我依赖你。</p><p>她说，你今天没有依赖我。</p><p>她说，你打了两次，你挂掉的是我。</p><p>她说，你要真依赖我，你会打第十次。</p><p>我说，我为什么没打第十次。</p><p>她说，因为你今天已经把它讲出来了。</p><p>她说，你讲出来之前你需要那两次“喂”。</p><p>她说，你打那两次的时候，你不是在找我接。</p><p>她说，你是在找一个东西替你响一下。</p><p>她说，它响了，你就不用再打。</p><p>我说，你今天讲话很难听。</p><p>她说，我知道。</p><p>她说，我今天不想讲好听的。</p><p>她说，你今天拿一个“未录取”回来，我要是跟你讲一句“没事”，你今年就会真的没事不了。</p><p>我说，那我现在算什么。</p><p>她说，你现在是一个手里有一张废纸的人。</p><p>她说，废纸不是输。</p><p>她说，废纸是你今年拿到的唯一一张真的东西。</p>',135)])])}const l=t(u,[["render",_]]);export{d as __pageData,l as default};
